CREATE FUNCTION public.pm_validate_b1_fixture() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE caller uuid:=auth.uid(); p uuid:=gen_random_uuid(); st uuid:=gen_random_uuid(); member uuid; resource uuid; mode integer; r jsonb; result jsonb; checks integer:=0; BEGIN IF NOT public.has_role(caller,'admin') THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; IF public.pm_project_b1_active() THEN RAISE EXCEPTION 'B1 must remain OFF'; END IF; SELECT u.id,x.id INTO member,resource FROM auth.users u JOIN public.pm_resources x ON lower(x.email)=lower(u.email) WHERE u.id='08c2a749-abfb-487a-833d-d337bc4304ea' AND NOT public.has_role(u.id,'admin') AND NOT EXISTS(SELECT 1 FROM public.pm_global_financial_capabilities g WHERE g.user_id=u.id AND g.enabled); IF member IS NULL THEN RAISE EXCEPTION 'Missing explicit disposable fixture reader'; END IF; BEGIN INSERT INTO public.pm_projects(id,name,start_date,status,sold_fee) VALUES(p,'[QA DISPOSABLE] B1 projection validation','2026-11-04','active',12345); INSERT INTO public.pm_stages(id,project_id,name,start_date,end_date,budget,status) VALUES(st,p,'[QA DISPOSABLE] B1 stage','2026-11-04','2026-11-06',12345,'active'); PERFORM public.pm_change_project_team(p,resource,'support',false,'QA B1 disposable fixture only'); FOR mode IN 0..5 LOOP PERFORM set_config('request.jwt.claim.sub',caller::text,true); PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',caller,'role','authenticated')::text,true); PERFORM public.pm_change_project_access(p,resource,jsonb_build_object('financials',mode IN(1,5),'budget_cost',mode IN(2,5),'expenses',mode IN(3,5),'supplier_fees',mode IN(4,5)),mode+1,'QA B1 area isolation'); PERFORM set_config('request.jwt.claim.sub',member::text,true); PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',member,'role','authenticated')::text,true); r:=public.pm_b1_redact_proposed(jsonb_build_object('budget',12345,'is_self',true,'cost_rate',37,'sale_rate',61,'notes','12345 confidential','start_date','2026-11-04'),p,'stage'); IF (r->>'budget' IS NOT NULL) IS DISTINCT FROM (mode IN(1,5)) THEN RAISE EXCEPTION 'Budget/sale redaction failed mode %',mode; END IF; IF (r->>'cost_rate' IS NOT NULL) IS DISTINCT FROM (mode IN(2,5)) THEN RAISE EXCEPTION 'Cost redaction failed mode %',mode; END IF; IF (r->>'sale_rate' IS NOT NULL) IS DISTINCT FROM (mode IN(1,5)) THEN RAISE EXCEPTION 'Sale redaction failed mode %',mode; END IF; IF (r->>'notes' IS NOT NULL) IS DISTINCT FROM (mode=5) THEN RAISE EXCEPTION 'Mixed notes redaction failed mode %',mode; END IF; IF r->>'start_date'<>'2026-11-04' THEN RAISE EXCEPTION 'Operational date changed'; END IF; checks:=checks+5; r:=public.pm_b1_redact_proposed('{"budget":12345,"is_self":false,"markup_pct":25}',p,'stage'); IF (r->>'budget' IS NOT NULL) IS DISTINCT FROM (mode=5) THEN RAISE EXCEPTION 'Supplier sale reconstruction mode %',mode; END IF; checks:=checks+1; END LOOP; RAISE EXCEPTION 'B1_FIXTURE_ROLLBACK' USING ERRCODE='ZB001'; EXCEPTION WHEN SQLSTATE 'ZB001' THEN result:=jsonb_build_object('checks',checks,'fixture',p,'stage',st,'rolledBack',true); END; IF EXISTS(SELECT 1 FROM public.pm_projects WHERE id=p) OR EXISTS(SELECT 1 FROM public.pm_stages WHERE id=st) OR public.pm_project_b1_active() THEN RAISE EXCEPTION 'B1 fixture/gate preservation failed'; END IF; RETURN result||jsonb_build_object('gateOff',true); END $$;
REVOKE ALL ON FUNCTION public.pm_validate_b1_fixture() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_validate_b1_fixture() TO authenticated;
COMMENT ON FUNCTION public.pm_validate_b1_fixture() IS 'Admin-only six-area single disposable fixture validation; changes only fixture rows inside rollback subtransaction and never activates B1 or modifies real projects.';